-- Seed the real Batch 11 active voter list from active-voter-list.csv.
-- Roll is retained as student_id (unique; with the discipline short code it forms a
-- second profile URL, /members/<short-code>-<roll>); the slug is the slugified name ("-2" on collisions).
-- Phone and email come from the source CSV.
-- All imported rows are regular active members. Role and status are not
-- present in the CSV, so no admin privileges or non-active states are inferred.
-- The CSV uses BAD for Business Administration (BA) and BANGLA for Bangla (BAN).
-- Depends on seed_disciplines.sql having run first.


-- The roster comes with real names, so these members skip the first-login confirmation step.
update members set profile_completed_at = now() where profile_completed_at is null;
